let authResolved=false;
function realAccount(){return window.MarbleDBState?.status==="ready"?window.MarbleDBState.account:null}
function isRealBuyer(){return !!window.MarbleAuthUser&&realAccount()?.profile.account_role==="buyer"}
function canShowRequestAction(){return authResolved&&(!window.MarbleAuthUser||isRealBuyer())}
function canRequestEquipment(){return !!window.MarbleAuthUser&&(isRealBuyer()||isActiveSupplier()||isActiveService())}
function canShowEquipmentAction(){return authResolved&&(!window.MarbleAuthUser||canRequestEquipment())}
function requestRoleMessage(){
  if(!realAccount())return tr("buyerOnly");
  if(isServiceSession())return ({
    tr:"Hizmet sağlayıcı taş alım talebi açamaz; üyeliği aktifse Makine & Sarf bölümünden talep açabilir.",
    en:"Service providers cannot request stone; active companies can request equipment and supplies.",
    zh:"服务企业不能发布石材采购需求；有效企业可发布设备及耗材需求。",
    ar:"لا يمكن لشركات الخدمات طلب الحجر؛ ويمكن للشركات النشطة طلب الآلات والمستلزمات."
  })[state.lang];
  return ({
    tr:"Taş alım talebini yalnızca alıcı hesabı açabilir. Aktif satıcılar Makine & Sarf ve Hizmetler bölümünden talep açabilir.",
    en:"Only buyers can request stone. Active suppliers can request equipment or services.",
    zh:"仅买家可发布石材采购需求；有效供应商可发布设备或服务需求。",
    ar:"طلبات الحجر للمشترين فقط؛ ويمكن للموردين النشطين طلب المعدات أو الخدمات."
  })[state.lang]||tr("buyerOnly");
}
function isActiveSupplier(){return !!window.MarbleAuthUser&&realAccount()?.activeSupplier===true}
function isActiveService(){return !!window.MarbleAuthUser&&realAccount()?.activeService===true}
function isSupplierSession(){return realAccount()?.profile.account_role==="supplier"}
function isServiceSession(){return realAccount()?.profile.account_role==="service"}
function isBusinessSession(){return isSupplierSession()||isServiceSession()}
function canShowPanelAction(){if(state.tab==="home")return false;return state.tab==="companies"||
  (state.tab==="services"?isActiveSupplier():state.tab==="machines"?canShowEquipmentAction():state.tab!=="requests"&&canShowRequestAction())}
function serviceCopy(){return serviceFlowCopy[state.lang]||serviceFlowCopy.tr}
function canOfferOnRequest(request){return !!request&&request.status==="open"&&request.buyer_id!==window.MarbleAuthUser?.id&&
  (request.format==="service"?isActiveService():isActiveSupplier())}
function liveRequest(id){return window.MarbleDBState?.requests?.find(x=>x.id===id)}
function visibleTabs(){return isBusinessSession()?["home","stones","companies","requests","machines","services"]:["home",...tabs]}
function requestCopy(){return isServiceSession()?{...requestCategoryCopy[state.lang],...serviceCopy()}:requestCategoryCopy[state.lang]||requestCategoryCopy.tr}
function tabLabel(tab){return tab==="home"?homeUi[state.lang].home:tab==="requests"?requestCopy().nav:tr("nav")[tabs.indexOf(tab)]}
function ensureVisibleTab(){if(state.tab==="requests"&&!isBusinessSession()&&authResolved){if(window.MarbleAuthUser&&window.MarbleDBState?.status!=="ready"&&window.MarbleDBState?.status!=="error")return;state.tab="stones";history.replaceState(null,"","/tr/dogal-tas");syncPageMetadata()}}
const $=id=>document.getElementById(id);
const seoConfig=JSON.parse($("mb-page-seo")?.textContent||"{}");
function syncPageMetadata(){
  if(location.pathname==="/tr/profil")return;
  const slug=location.pathname.split("/")[2];
  const seo=slug===marketplacePaths.requests?{title:requestCategoryCopy.tr.title,description:requestCategoryCopy.tr.description}:seoConfig.pages?.[slug]||seoConfig.home;
  if(!seo)return;
  const title=seo.title.toLocaleLowerCase("tr-TR").includes("marble borsa")?seo.title:`${seo.title} | Marble Borsa`;
  document.title=title;
  const setMeta=(selector,value)=>{const el=document.querySelector(selector);if(el)el.setAttribute("content",value)};
  setMeta('meta[name="description"]',seo.description);
  setMeta('meta[property="og:title"]',title);
  setMeta('meta[property="og:description"]',seo.description);
  setMeta('meta[name="twitter:title"]',title);
  setMeta('meta[name="twitter:description"]',seo.description);
  const robots=document.querySelector('meta[name="robots"]')||document.head.appendChild(Object.assign(document.createElement("meta"),{name:"robots"}));
  robots.setAttribute("content",slug===marketplacePaths.requests||!seoConfig.allowIndexing?"noindex,nofollow":"index,follow");
  if(seoConfig.siteUrl){
    const canonicalPath=slug===marketplacePaths.requests||seoConfig.pages?.[slug]?location.pathname:"/";
    const url=new URL(canonicalPath,seoConfig.siteUrl).toString();
    const canonical=document.querySelector('link[rel="canonical"]');
    if(canonical)canonical.setAttribute("href",url);
    setMeta('meta[property="og:url"]',url);
  }
}
