function renderGuideLocalized(){
 const t=guideUi[state.lang]||guideUi.tr;
 const path=state.lang==="tr"?"/tr/rehber":`/${state.lang}/guide`;
 const kicker=document.getElementById("guide-preview-kicker"), title=document.getElementById("guide-preview-heading"), desc=document.getElementById("guide-preview-desc"), preview=document.getElementById("guide-preview-link"), footer=document.getElementById("footer-guide");
 if(kicker)kicker.textContent=t.eyebrow;
 if(title)title.textContent=t.title;
 if(desc)desc.textContent=t.desc;
 if(preview){preview.textContent=t.link;preview.href=path;}
 if(footer){footer.textContent=t.name;footer.href=path;}
 const text=sourcingUi[state.lang]||sourcingUi.tr;
 const pathSlug={tr:['mermer-teklifi-al','b2b-mermer'],en:['request-marble-quotes','b2b-marble'],zh:['request-marble-quotes','b2b-marble'],ar:['request-marble-quotes','b2b-marble']}[state.lang]||['mermer-teklifi-al','b2b-mermer'];
 for(const [topic,slug] of [['quote',pathSlug[0]],['b2b',pathSlug[1]]]){
   const values=text[topic];
   for(const [suffix,content] of [['kicker',values[0]],['title',values[1]],['desc',values[2]],['action',values[3]]]){
     const element=document.getElementById('sourcing-'+topic+'-'+suffix);
     if(element) element.textContent=content;
   }
   const link=document.getElementById('sourcing-'+topic+'-link');
   if(link) link.href='/'+state.lang+'/'+slug;
 }
}
