    `<p class="catalog-empty">${({tr:"Bu firma henüz katalog kaydı eklemedi.",en:"This company has not added catalogue items yet.",zh:"该企业尚无目录内容。",ar:"لم تضف هذه الشركة عناصر بعد."})[state.lang]}</p>`;
